"""Fail-closed P03 decision. Missing evidence blocks P04; no deployment occurs."""
import argparse
from datetime import datetime, timezone
import hashlib
import json
from pathlib import Path
import re
import time
import math

from p03_candidate import candidate_manifest
from p03_scope import SCOPES, DEFERRED_COMPONENTS, NON_AI_E2E_CASES, load_profile, quality_deferred, validate_scope

LOCAL = Path(__file__).resolve().parent / '.local' / 'p03'
ROOT = Path(__file__).resolve().parents[2]

# Named cases describe required evidence, not attestations generated by this tool.
REQUIRED_CASES = {
    'contracts': {'producer_consumer', 'frontend_contracts', 'old_new_compatibility', 'enum_error_schema_evolution'},
    'security': {'endpoint_role_matrix', 'bola_idor', 'refresh_reuse', 'user_claim_revocation',
                 'upload', 'rate_limit', 'secret_pii_redaction'},
    'e2e': {*(f'F{i:02}' for i in range(1, 12)), 'business', 'import', 'ml'},
    'resilience': {'broker_outage', 'downstream_outage', 'crash_retry', 'duplicate_out_of_order',
                   'dlq_replay', 'rating_feature_reconciliation', 'snapshot_read'},
    'restore': {'six_databases', 'nonempty_objects', 'application_recovery', 'projection_watermark',
                'retention_deletion', 'license_revocation', 'rpo_rto'},
    'frontend': {'user', 'admin', 'business', 'responsive', 'keyboard', 'loading_error_empty', 'map', 'async_ack'},
    'operations': {'source_image_linkage', 'findings_review', 'trace_dashboard', 'replay_runbook',
                   'rollback_runbook', 'restore_runbook', 'deletion_runbook', 'alert_delivery'},
    'providers': {'provider_inventory', 'real_sandbox_scope', 'license_credentials', 'external_latency'},
}


def cases_pass(report, required):
    checks = report.get('checks')
    if not isinstance(checks, list) or not checks:
        return False
    seen = set()
    for check in checks:
        if not isinstance(check, dict) or check.get('status') != 'PASS' or check.get('pass', True) is not True:
            return False
        name = check.get('id')
        references = check.get('evidence')
        if (not isinstance(name, str) or not name.strip() or name in seen
                or not isinstance(references, list) or not references
                or any(not isinstance(ref, str) or not ref.strip() for ref in references)):
            return False
        seen.add(name)
    return required <= seen


def number(value):
    try:
        return type(value) in (int, float) and math.isfinite(value)
    except OverflowError:
        return False


def successful_counts(value, requests):
    counts = value.get('status_counts')
    return (isinstance(counts, dict) and bool(counts)
            and all(isinstance(code, str) and re.fullmatch(r'2\d\d', code)
                    and type(count) is int and count > 0 for code, count in counts.items())
            and sum(counts.values()) == requests
            and number(value.get('error_rate')) and value['error_rate'] == 0)


def quality_pass(report):
    if (report.get('status') != 'OFFLINE_METRIC_GATE_PASS'
            or report.get('owner_lineage_license_reviewed') is not True
            or report.get('reasons') != []
            or type(report.get('users')) is not int or report['users'] < 100
            or type(report.get('holdout_interactions')) is not int or report['holdout_interactions'] < 1000):
        return False
    metrics = report.get('metrics', {})
    for name in ('basic', 'model'):
        values = metrics.get(name, {})
        if not all(number(values.get(key)) and 0 <= values[key] <= 1 for key in ('precision_at_10', 'ndcg_at_10')):
            return False
    return (metrics['model']['ndcg_at_10'] + 1e-12 >= metrics['basic']['ndcg_at_10'] + .02
            and metrics['model']['precision_at_10'] + 1e-12 >= metrics['basic']['precision_at_10'])


def load_pass(report, scope='full'):
    profile = load_profile(json.loads((ROOT / 'backend/contracts/fixtures/load-profile.json').read_text(encoding='utf-8')), scope)
    measured = report.get('metrics', {})
    counts = report.get('dataset_counts', {})
    if (report.get('evaluation', {}).get('p00_release_gate_pass') is not True
            or report.get('evaluation', {}).get('reasons') != []
            or type(measured.get('requests')) is not int or measured['requests'] <= 0
            or type(measured.get('errors')) is not int or measured['errors'] != 0
            or type(measured.get('skipped_slots')) is not int or measured['skipped_slots'] != 0
            or type(measured.get('achieved_virtual_users')) is not int
            or measured['achieved_virtual_users'] < profile['concurrent_users']
            or not successful_counts(measured, measured['requests'])
            or not number(measured.get('elapsed_seconds')) or measured['elapsed_seconds'] < 3
            or not number(measured.get('actual_rps'))
            or measured['actual_rps'] < profile['target_requests_per_second'] * .95
            or abs(measured['actual_rps'] - measured['requests'] / measured['elapsed_seconds']) > .01
            or type(report.get('authenticated_principals')) is not int
            or report['authenticated_principals'] < profile['concurrent_users']):
        return False
    dataset_keys = ('places', 'users', 'reviews', 'trips', 'interactions') if scope == 'full' else ('places', 'users', 'reviews', 'trips')
    if any(type(counts.get(key)) is not int or counts[key] < profile[key]
           for key in dataset_keys):
        return False
    classes = report.get('class_metrics', {})
    if scope == 'non-ai' and set(classes) != set(profile['mix']):
        return False
    total = 0
    for name, fraction in profile['mix'].items():
        value = classes.get(name, {})
        target = 'basic_recommendation_p95' if name == 'basic_recommendation' else 'write_p95' if name == 'authenticated_write' else 'read_p95'
        count = value.get('requests')
        if (type(count) is not int or count <= 0 or type(value.get('errors')) is not int or value['errors'] != 0
                or not successful_counts(value, count)
                or value.get('pass') is not True or not number(value.get('p95_ms'))
                or not 0 <= value['p95_ms'] <= profile['latency_target_ms'][target]
                or abs(count - measured['requests'] * fraction) > 1):
            return False
        total += count
    return total == measured['requests'] and report.get('fixture_name_restored') is True


def evidence_metadata(report, release_id, now, reviewed_hashes):
    if not isinstance(report, dict) or not isinstance(release_id, str) or not release_id.strip():
        return False
    if report.get('release_id') != release_id:
        return False
    try:
        timestamp = datetime.fromisoformat(report['timestamp'].replace('Z', '+00:00'))
        if timestamp.tzinfo is None or not 0 <= (now - timestamp).total_seconds() <= 86400:
            return False
    except (KeyError, ValueError, TypeError, AttributeError):
        return False
    sources = report.get('source_hashes')
    if not isinstance(sources, dict) or not sources or not isinstance(reviewed_hashes, dict):
        return False
    for name, digest in sources.items():
        if (not isinstance(name, str) or not name or not isinstance(digest, str)
                or re.fullmatch('[0-9a-f]{64}', digest) is None or reviewed_hashes.get(name) != digest):
            return False
        path = (ROOT / name).resolve()
        if not path.is_relative_to(ROOT.resolve()) or not path.is_file():
            return False
        try:
            if hashlib.sha256(path.read_bytes()).hexdigest() != digest:
                return False
        except OSError:
            return False
    return True


def decision(reports, release_id=None, now=None, scope='full'):
    now = now or datetime.now(timezone.utc)
    try:
        validate_scope(scope)
    except ValueError:
        return {'status': 'NO_GO', 'scope': scope, 'p04_authorized_by_gate': False,
                'system_verified': False, 'production_authorized': False,
                'checks': [{'gate': 'scope', 'pass': False, 'reason': 'Unknown P03 scope'}],
                'release_id': release_id, 'candidate_sha256': None}
    if not isinstance(reports, dict):
        reports = {}
    operations = reports.get('operations', {})
    if not isinstance(operations, dict):
        operations = {}
    reviewed_hashes = operations.get('reviewed_source_hashes', {})
    linkage_reviewed = operations.get('release_linkage_reviewed') is True
    try:
        manifest = candidate_manifest()
        candidate = manifest['sha256'] if manifest['files'] else None
    except (OSError, ValueError):
        candidate = None
    requirements = {
        'contracts': lambda v: v.get('pass') is True,
        'security': lambda v: v.get('pass') is True and v.get('full_role_matrix_pass') is True,
        'e2e': lambda v: v.get('f01_f11_pass') is True and v.get('business_import_ml_pass') is True,
        'resilience': lambda v: v.get('pass') is True and v.get('reconciliation_pass') is True,
        'load': lambda v: load_pass(v, scope),
        'restore': lambda v: v.get('pass_checks') is True and v.get('application_disaster_recovery_verified') is True,
        'frontend': lambda v: bool(v.get('checks')) and not v.get('gaps') and all(c.get('status') == 'PASS' for c in v['checks']),
        'quality': quality_pass,
        'operations': lambda v: v.get('runbooks_reviewed') is True and bool(v.get('alert_recipient')) and type(v.get('critical_high_open')) is int and v['critical_high_open'] == 0 and linkage_reviewed,
        'providers': lambda v: v.get('release_scope_coverage_approved') is True,
    }
    required_cases = dict(REQUIRED_CASES)
    if scope == 'non-ai':
        required_cases['e2e'] = NON_AI_E2E_CASES
        required_cases['resilience'] = (REQUIRED_CASES['resilience'] - {'rating_feature_reconciliation'}) | {'rating_reconciliation', 'slow_consumer_backpressure'}
        requirements['e2e'] = lambda v: (v.get('non_ai_f_cases_pass') is True
            and v.get('business_import_pass') is True and v.get('non_ai_admin_pass') is True
            and not any(c.get('id') in {'F05', 'F08', 'ml'} for c in v.get('checks', [])))
        requirements['quality'] = quality_deferred
    checks = []
    for name, accepts in requirements.items():
        report = reports.get(name)
        try:
            report_scope = report.get('scope', 'full') if isinstance(report, dict) else None
            metadata_pass = (report_scope == scope and candidate is not None and linkage_reviewed and evidence_metadata(report, release_id, now, reviewed_hashes)
                             and report.get('candidate_sha256') == candidate
                             and report.get('candidate_before_sha256') == candidate
                             and operations.get('reviewed_candidate_sha256') == candidate)
            passed = (metadata_pass and accepts(report)
                      and (name not in required_cases or cases_pass(report, required_cases[name])))
            if passed:
                passed = not report.get('pending_cases') and not report.get('error') and report.get('status') not in {'FAIL', 'FAILED', 'NO_GO'}
            if passed and scope == 'non-ai' and name == 'frontend':
                passed = (type(report.get('ai_http_requests')) is int and report['ai_http_requests'] == 0
                          and type(report.get('page_errors')) is int and report['page_errors'] == 0)
            if passed and scope == 'non-ai' and name == 'restore':
                privacy = report.get('privacy_state_preservation', {})
                passed = (privacy.get('deleted_user_state_preserved') is True
                          and privacy.get('revoked_storage_license_preserved') is True
                          and type(privacy.get('stale_versions_replayed_with_new_event_ids')) is int
                          and privacy['stale_versions_replayed_with_new_event_ids'] >= 2)
        except (TypeError, AttributeError, KeyError, ValueError, OSError):
            passed = False
        checks.append({'gate': name, 'pass': bool(passed), 'reason': 'Evidence accepted' if passed else
                       'Required evidence, release linkage, current source hashes, freshness or acceptance criteria not met'})
    accepted = all(c['pass'] for c in checks)
    if scope == 'non-ai':
        for check in checks:
            if check['gate'] == 'quality' and check['pass']:
                check.update(status='DEFERRED', reason='AI explicitly deferred; no AI acceptance granted')
    full_verified = accepted and scope == 'full'
    return {'status': ('SYSTEM_VERIFIED' if scope == 'full' else 'P03_NON_AI_VERIFIED') if accepted else 'NO_GO',
            'scope': scope, 'deferred_components': sorted(DEFERRED_COMPONENTS) if scope == 'non-ai' else [],
            'system_verified': full_verified, 'production_authorized': False,
            'p04_authorized_by_gate': full_verified, 'checks': checks,
            'release_id': release_id, 'candidate_sha256': candidate}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--evidence-dir', type=Path, default=LOCAL)
    parser.add_argument('--release-id', help='Explicit release identity; omitted identity always returns NO_GO')
    parser.add_argument('--scope', choices=SCOPES, default='full', help='Explicit acceptance scope; AI remains deferred in non-ai')
    args = parser.parse_args()
    reports, files = {}, {}
    # Simple probe filenames plus dedicated release evidence use a fixed map.
    names = {'contracts': 'contracts.json', 'security': 'security.json', 'load': 'mix-load.json',
             'quality': 'quality-report.json', 'frontend': 'frontend-browser/report.json',
             'restore': 'restore-report.json', 'e2e': 'e2e-report.json',
             'resilience': 'resilience-report.json', 'operations': 'operations-report.json',
             'providers': 'providers-report.json'}
    for name, relative in names.items():
        path = args.evidence_dir / relative
        if path.is_file():
            # Freshness is bounded, but same-release source/image linkage still requires review.
            raw = path.read_bytes()
            try:
                value = json.loads(raw)
            except (ValueError, UnicodeError):
                files[name] = {'sha256': hashlib.sha256(raw).hexdigest(), 'fresh': False, 'invalid_json': True}
                continue
            files[name] = {'sha256': hashlib.sha256(raw).hexdigest(),
                           'fresh': 0 <= time.time() - path.stat().st_mtime <= 86400}
            if files[name]['fresh']:
                reports[name] = value
    report = decision(reports, args.release_id, scope=args.scope)
    operations = reports.get('operations', {})
    linkage_reviewed = isinstance(operations, dict) and operations.get('release_linkage_reviewed') is True
    report.update(timestamp=datetime.now(timezone.utc).isoformat(), evidence=files,
                  acceptance_notice='P03 acceptance; does not replace production approval',
                  release_linkage_review_required=not linkage_reviewed)
    LOCAL.mkdir(parents=True, exist_ok=True)
    (LOCAL / 'gate-report.json').write_text(json.dumps(report, indent=2), encoding='utf-8')
    print(json.dumps(report, indent=2))
    return 0 if report['status'] in {'SYSTEM_VERIFIED', 'P03_NON_AI_VERIFIED'} else 2


if __name__ == '__main__':
    raise SystemExit(main())
